"""Early-departure version (generated by twoleg/make_cpsat_early.py from cpsat_validate_twoleg.py). D19: exact CP-SAT model of Section 3 on small instances, checked against the simulator, with PGND and lookahead gaps.

Usage: python cpsat_validate.py pilot|main --seeds 390-391 --jobs 3,4,5,6 --limit 300 --workers 8 --out cpsat/...
Writes one JSON per case to --out. Writes only to cpsat/.
"""
from __future__ import annotations

import argparse
import itertools
import json
import math
import os
from pathlib import Path
from time import perf_counter

from ortools.sat.python import cp_model

OBJ = ("makespan", "tardiness", "energy")
ESCALE = 10**6


def instance_for(seed, level, n_jobs):
    from su_modfjsp_ha_pc.generator import generate_instance
    from su_modfjsp_ha_pc.structural import realize_structural_events
    raw = generate_instance(level, "small", seed)
    true = realize_structural_events(raw).instance
    return true.replace(instance_id=f"{true.instance_id}_first{n_jobs}", jobs=true.jobs[:n_jobs])


def merged_windows(instance, event_types, entity):
    spans = sorted((e.event_time, e.event_time + e.duration) for e in instance.events
                   if e.event_type in event_types and e.affected_entity == entity and e.duration > 0)
    out = []
    for s, t in spans:
        if out and s <= out[-1][1]:
            out[-1] = (out[-1][0], max(out[-1][1], t))
        else:
            out.append((s, t))
    return out


def route_set(instance, src, dst):
    """Superset of the decoder's candidate routes: shortest path avoiding any subset of event edges, with or without bottlenecks."""
    from su_modfjsp_ha_pc.path_conflict_transport_decoder import _shortest_path_avoiding
    if src == dst:
        return [()]
    event_edges = sorted({e.affected_entity for e in instance.events if e.event_type in {"path_blockage", "congestion_spike"} and e.duration > 0})
    bottlenecks = frozenset(e.edge_id for e in instance.path_edges if e.is_bottleneck)
    routes = []
    for r in range(len(event_edges) + 1):
        for subset in itertools.combinations(event_edges, r):
            for extra in (frozenset(), bottlenecks):
                route = _shortest_path_avoiding(instance.path_edges, source=src, target=dst, avoid_edges=frozenset(subset) | extra)
                if route is not None and route not in routes:
                    routes.append(route)
    return routes


def solve(instance, objective, limit, workers, hint=None):
    from su_modfjsp_ha_pc.path_conflict_neural_dataset import _route_length
    m = cp_model.CpModel()
    machines = {mc.machine_id: mc for mc in instance.machines}
    agvs = list(instance.agvs)
    edges = {e.edge_id: e for e in instance.path_edges}
    ops = [(job, i, op) for job in instance.jobs for i, op in enumerate(job.operations)]
    n = len(ops)
    starts = {a.start_node_id for a in agvs}
    dest_nodes = sorted({machines[mid].node_id for _, _, op in ops for mid in op.eligible_machines})
    node_ids = sorted(set(dest_nodes) | starts)
    nidx = {nd: k for k, nd in enumerate(node_ids)}
    depot = agvs[0].start_node_id
    routes = {(s, d): route_set(instance, s, d) for s in node_ids for d in node_ids}

    max_travel = 2 * max(max(1, math.ceil(_route_length(instance, r) / a.speed)) for rs in routes.values() for r in rs for a in agvs)
    H = (sum(max(op.processing_time.values()) + max_travel for _, _, op in ops) + sum(e.duration for e in instance.events if e.duration > 0)
         + max(job.release_time for job in instance.jobs) + 10)

    S, E, TS, TE, X, R, dest, src = {}, {}, {}, {}, {}, {}, {}, {}
    ETE, TLB = {}, {}
    agv_leg_iv = {a.agv_id: [] for a in agvs}
    machine_iv = {mid: [] for mid in machines}
    agv_iv = {a.agv_id: [] for a in agvs}
    edge_iv = {eid: [] for eid in edges}
    proc_energy, trans_energy = [], []
    for o, (job, i, op) in enumerate(ops):
        S[o], E[o] = m.NewIntVar(0, H, f"S{o}"), m.NewIntVar(0, H, f"E{o}")
        TS[o], TE[o] = m.NewIntVar(0, H, f"TS{o}"), m.NewIntVar(0, H, f"TE{o}")
        ETE[o], TLB[o] = m.NewIntVar(0, H, f"ETE{o}"), m.NewIntVar(0, H, f"TLB{o}")
        lits = []
        for mid in op.eligible_machines:
            x = m.NewBoolVar(f"x{o}_{mid}")
            X[o, mid] = x
            lits.append(x)
            p = op.processing_time[mid]
            machine_iv[mid].append(m.NewOptionalIntervalVar(S[o], p, E[o], x, f"mi{o}_{mid}"))
            proc_energy.append((round(op.processing_energy[mid] * ESCALE), x))
        m.AddExactlyOne(lits)
        dest[o] = m.NewIntVar(0, len(node_ids) - 1, f"dest{o}")
        m.Add(dest[o] == sum(nidx[machines[mid].node_id] * X[o, mid] for mid in op.eligible_machines))
        src[o] = m.NewIntVar(0, len(node_ids) - 1, f"src{o}")
        # route choice: (agv, src node, dest node, route)
        rl, by_agv = [], {a.agv_id: [] for a in agvs}
        if i == 0:
            pick_nodes = [depot]
        else:
            prev_op = ops[o - 1][2]
            pick_nodes = sorted({machines[mid].node_id for mid in prev_op.eligible_machines})
        for a in agvs:
            for s_node in node_ids:
                for p_node in pick_nodes:
                    for d_node in sorted({machines[mid].node_id for mid in op.eligible_machines}):
                        for ke, r_e in enumerate(routes[s_node, p_node]):
                            for kl, r_l in enumerate(routes[p_node, d_node]):
                                route = tuple(r_e) + tuple(r_l)
                                lit = m.NewBoolVar(f"r{o}_{a.agv_id}_{s_node}_{p_node}_{d_node}_{ke}_{kl}")
                                R[o, a.agv_id, s_node, d_node, route, p_node] = lit
                                rl.append(lit)
                                by_agv[a.agv_id].append(lit)
                                length = _route_length(instance, route)
                                te = math.ceil(_route_length(instance, r_e) / a.speed) if r_e else 0
                                tl = max(1, math.ceil(_route_length(instance, r_l) / a.speed))
                                m.Add(src[o] == nidx[s_node]).OnlyEnforceIf(lit)
                                m.Add(dest[o] == nidx[d_node]).OnlyEnforceIf(lit)
                                if i > 0:
                                    m.Add(dest[o - 1] == nidx[p_node]).OnlyEnforceIf(lit)
                                m.Add(ETE[o] == TS[o] + te).OnlyEnforceIf(lit)
                                m.Add(TE[o] == TLB[o] + tl).OnlyEnforceIf(lit)
                                trans_energy.append((round(round(length * a.consumption_rate, 6) * ESCALE), lit))
                                for eid in sorted(set(r_e)):
                                    edge_iv[eid].append(((o, "e"), lit, te))
                                for eid in sorted(set(r_l)):
                                    edge_iv[eid].append(((o, "l"), lit, tl))
        m.AddExactlyOne(rl)
        Y = {}
        for a in agvs:
            y = m.NewBoolVar(f"y{o}_{a.agv_id}")
            m.Add(sum(by_agv[a.agv_id]) == y)
            Y[a.agv_id] = y
            agv_iv[a.agv_id].append(m.NewOptionalIntervalVar(TS[o], m.NewIntVar(1, H, f"td{o}_{a.agv_id}"), TE[o], y, f"ai{o}_{a.agv_id}"))
            agv_leg_iv[a.agv_id].append(m.NewOptionalIntervalVar(TS[o], m.NewIntVar(0, H, f"tde{o}_{a.agv_id}"), ETE[o], y, f"aie{o}_{a.agv_id}"))
            agv_leg_iv[a.agv_id].append(m.NewOptionalIntervalVar(TLB[o], m.NewIntVar(1, H, f"tdl{o}_{a.agv_id}"), TE[o], y, f"ail{o}_{a.agv_id}"))
        ops[o] = (job, i, op, Y)
        # precedence: transport after predecessor completes (or release), arrival before processing
        prev = o - 1 if i > 0 else None
        m.Add(TLB[o] >= (E[prev] if prev is not None else job.release_time))
        m.Add(TLB[o] >= ETE[o])
        m.Add(S[o] >= TE[o])
        if prev is not None:
            m.Add(S[o] >= E[prev])

    # machines: no overlap with each other or with breakdown windows
    for mid, ivs in machine_iv.items():
        fixed = [m.NewIntervalVar(s, t - s, t, f"mb_{mid}_{s}") for s, t in merged_windows(instance, {"machine_breakdown"}, mid)]
        m.AddNoOverlap(ivs + fixed)
    # AGVs: no overlap, failure windows, and location carried by a circuit over tasks
    for a in agvs:
        fixed = [m.NewIntervalVar(s, t - s, t, f"af_{a.agv_id}_{s}") for s, t in merged_windows(instance, {"agv_failure"}, a.agv_id)]
        m.AddNoOverlap(agv_iv[a.agv_id])
        m.AddNoOverlap(agv_leg_iv[a.agv_id] + fixed)
        arcs = []
        depot = n
        used = m.NewBoolVar(f"used_{a.agv_id}")
        arcs.append((depot, depot, used.Not()))
        for o in range(n):
            y = ops[o][3][a.agv_id]
            arcs.append((o, o, y.Not()))
            first = m.NewBoolVar(f"first{o}_{a.agv_id}")
            last = m.NewBoolVar(f"last{o}_{a.agv_id}")
            arcs += [(depot, o, first), (o, depot, last)]
            m.Add(src[o] == nidx[a.start_node_id]).OnlyEnforceIf(first)
            m.AddImplication(first, used)
            for p in range(n):
                if p == o:
                    continue
                lit = m.NewBoolVar(f"arc{p}_{o}_{a.agv_id}")
                arcs.append((p, o, lit))
                m.Add(src[o] == dest[p]).OnlyEnforceIf(lit)
                m.Add(TS[o] >= TE[p]).OnlyEnforceIf(lit)
        m.AddCircuit(arcs)
    # edges: capacity over the whole move, and no traversal during blockage or congestion windows
    for eid, items in edge_iv.items():
        cap = edges[eid].capacity
        ivs, demands = [], []
        per_op = {}
        for o, lit, travel in items:
            per_op.setdefault(o, []).append(lit)
        for o, lits in per_op.items():
            u = m.NewBoolVar(f"u{o[0]}{o[1]}_{eid}")
            m.Add(sum(lits) == u)
            leg_s, leg_e = (TS[o[0]], ETE[o[0]]) if o[1] == "e" else (TLB[o[0]], TE[o[0]])
            ivs.append(m.NewOptionalIntervalVar(leg_s, m.NewIntVar(0, H, f"ed{o[0]}{o[1]}_{eid}"), leg_e, u, f"ei{o[0]}{o[1]}_{eid}"))
            demands.append(1)
        for s, t in merged_windows(instance, {"path_blockage", "congestion_spike"}, eid):
            ivs.append(m.NewIntervalVar(s, t - s, t, f"ew_{eid}_{s}"))
            demands.append(cap)
        if ivs:
            m.AddCumulative(ivs, demands, cap)

    last_ops = {}
    for o, (job, i, op, _) in enumerate(ops):
        last_ops[job.job_id] = o
    cmax = m.NewIntVar(0, H, "cmax")
    m.AddMaxEquality(cmax, [E[o] for o in last_ops.values()])
    tard = []
    for job in instance.jobs:
        t = m.NewIntVar(0, H, f"tard_{job.job_id}")
        m.Add(t >= E[last_ops[job.job_id]] - job.due_date)
        tard.append(t)
    energy = sum(c * lit for c, lit in proc_energy) + sum(c * lit for c, lit in trans_energy)
    target = {"makespan": cmax, "tardiness": sum(tard), "energy": energy}[objective]
    m.Minimize(target)
    if hint is not None:
        for o, (start, end, mid, ts, te) in hint.items():
            m.AddHint(S[o], start)
            m.AddHint(TS[o], ts)
            for (oo, mm), x in X.items():
                if oo == o:
                    m.AddHint(x, int(mm == mid))

    solver = cp_model.CpSolver()
    solver.parameters.max_time_in_seconds = limit
    solver.parameters.num_search_workers = workers
    started = perf_counter()
    status = solver.Solve(m)
    wall = perf_counter() - started
    result = {"status": solver.StatusName(status), "wall_s": round(wall, 2), "n_ops": n, "horizon": H}
    if status not in (cp_model.OPTIMAL, cp_model.FEASIBLE):
        return result, None
    scale = ESCALE if objective == "energy" else 1
    result["objective"] = solver.ObjectiveValue() / scale
    result["bound"] = solver.BestObjectiveBound() / scale
    # schedule for the simulator
    from su_modfjsp_ha_pc.schedule import ScheduledOperation, ScheduleResult, TransportMove
    sched_ops, moves = [], []
    for o, (job, i, op, Y) in enumerate(ops):
        mid = next(mm for (oo, mm), x in X.items() if oo == o and solver.Value(x))
        sched_ops.append(ScheduledOperation(operation_id=op.operation_id, job_id=job.job_id, op_index=op.op_index, machine_id=mid,
                                            start=solver.Value(S[o]), end=solver.Value(E[o]), processing_energy=op.processing_energy[mid]))
        key = next(k for k, lit in R.items() if k[0] == o and solver.Value(lit))
        _, agv_id, s_node, d_node, route, _p = key
        agv = next(a for a in agvs if a.agv_id == agv_id)
        moves.append(TransportMove(move_id=f"T{o}", job_id=job.job_id, operation_id=op.operation_id, agv_id=agv_id, from_node=s_node,
                                   to_node=d_node, edge_ids=route, start=solver.Value(TS[o]), end=solver.Value(TE[o]),
                                   transport_energy=round(_route_length(instance, route) * agv.consumption_rate, 6)))
    return result, ScheduleResult(algorithm="cpsat", path_aware=True, operations=tuple(sched_ops), transports=tuple(moves), event_aware=True)


def run_case(seed, level, n_jobs, limit, workers, out, cpsat_only=False):
    if not cpsat_only:
        from event_blind import SCALES, MODEL_DIR, decode
    from su_modfjsp_ha_pc.metrics import evaluate_feasibility, evaluate_schedule
    from su_modfjsp_ha_pc.objective_contract import read_objective_scales
    from su_modfjsp_ha_pc.path_conflict_neural_dataset import _explicit_preference_id, _explicit_teacher_preferences
    from su_modfjsp_ha_pc.pgnd_v5_exact_certificate import neural_ensemble_proposal_selector
    from su_modfjsp_ha_pc.run_pgnd_v4_learnability_gate import _load_artifact
    from su_modfjsp_ha_pc.run_pgnd_v5_smoke import MEMBER_STATES

    inst = instance_for(seed, level, n_jobs)
    if not cpsat_only:
        scales = read_objective_scales(SCALES)
        selector = neural_ensemble_proposal_selector(tuple(_load_artifact(MODEL_DIR / f"pgnd_v4_member_{s}.pt") for s in MEMBER_STATES))
    prefs = _explicit_teacher_preferences(len(inst.objectives), max_preferences=6)
    for k, name in enumerate(OBJ):
        path = Path(out) / f"s{seed}_{level}_n{n_jobs}_{name}.json"
        if path.exists():
            continue
        index = next(ix for ix, p in enumerate(prefs) if abs(p[k] - 1.0) < 1e-9)
        pref = prefs[index]
        row = {"seed": seed, "level": level, "n_jobs": n_jobs, "objective": name, "pref_index": index}
        for method, sel in (() if cpsat_only else (("lookahead", None), ("pgnd", selector))):
            started = perf_counter()
            schedule, _ = decode(true=inst, raw=inst, preference=pref, level=level, seed=seed, mode="realized",
                                 preference_id=_explicit_preference_id(index, pref), selector=sel, scales=scales, clock="oracle")
            ev = evaluate_schedule(inst, schedule)
            from run_early import check_schedule
            bad, tbad, _m, _st = check_schedule(inst, schedule, "early")
            row[method] = {"value": ev[name], "feasible": ev["feasible"], "wall_s": round(perf_counter() - started, 2), "route_bad": bad, "timing_bad": tbad}
        res, sched = solve(inst, name, limit, workers)
        row["cpsat"] = res
        if sched is not None:
            ev = evaluate_schedule(inst, sched)
            rep = evaluate_feasibility(inst, sched)
            row["cpsat"]["sim_value"] = ev[name]
            row["cpsat"]["sim_feasible"] = ev["feasible"]
            row["cpsat"]["violations"] = {k2: v for k2, v in rep.__dict__.items() if v}
            from run_early import check_schedule
            bad, tbad, msgs, _st = check_schedule(inst, sched, "early")
            row["cpsat"]["route_bad"] = bad
            row["cpsat"]["timing_bad"] = tbad
            row["cpsat"]["route_msgs"] = msgs
        path.write_text(json.dumps(row, indent=1))
        print(json.dumps({k2: row[k2] for k2 in ("seed", "level", "n_jobs", "objective")}), row["cpsat"].get("status"),
              row["cpsat"].get("objective"), flush=True)


if __name__ == "__main__":
    ap = argparse.ArgumentParser()
    ap.add_argument("--seeds", default="390-391")
    ap.add_argument("--jobs", default="3")
    ap.add_argument("--levels", default="L4,L5")
    ap.add_argument("--limit", type=float, default=300)
    ap.add_argument("--workers", type=int, default=8)
    ap.add_argument("--out", required=True)
    ap.add_argument("--cpsat-only", action="store_true", help="skip the dispatcher comparison, which is not reported in the paper")
    args = ap.parse_args()
    os.makedirs(args.out, exist_ok=True)
    a, b = map(int, args.seeds.split("-"))
    for n_jobs in map(int, args.jobs.split(",")):
        for seed in range(a, b + 1):
            for level in args.levels.split(","):
                run_case(seed, level, n_jobs, args.limit, args.workers, args.out, args.cpsat_only)
